//! Semantic coverage probes, generated by the ONE shared mock encoder. These are
//! validation inputs and adversarial mutations, never claimed as real captures.
use crate::{Adapter, decode_recording, invalid};
use acyclic_harness_core::{
    Result,
    model::{ModelDispatch, ModelEvent},
};
use bytes::Bytes;
use futures::TryStreamExt as _;
use harness_mock_model::{CustomTool, Step, Tool, reply_with_usage};
use serde_json::json;

fn dispatch() -> ModelDispatch {
    ModelDispatch {
        operation_id: acyclic_harness_core::OperationId::new(),
        step: 0,
        request_digest: [0; 32],
    }
}

fn ordinary() -> Step {
    Step {
        text: vec!["answer λ".into()],
        tools: vec![Tool {
            id: "call".into(),
            name: "read".into(),
            namespace: None,
            arguments: json!({"source":{"path":"skill.md"}}),
        }],
        ..Step::default()
    }
}

fn chunks(step: &Step) -> Result<Vec<Bytes>> {
    Ok(reply_with_usage("responses", step, 7)
        .ok_or_else(|| invalid("missing semantic probe reply"))?
        .chunks
        .into_iter()
        .map(Bytes::from)
        .collect())
}

async fn projected(chunks: Vec<Bytes>) -> Result<Vec<ModelEvent>> {
    decode_recording(
        Adapter::Responses,
        Box::pin(futures::stream::iter(chunks.into_iter().map(Ok))),
        65536,
        dispatch(),
    )
    .await
}

#[tokio::test]
async fn strict_projection_preserves_supported_calls_text_and_usage_under_every_byte_cut()
-> Result<()> {
    let bytes: Vec<u8> = chunks(&ordinary())?.into_iter().flatten().collect();
    for cut in 0..=bytes.len() {
        let (head, tail) = bytes
            .split_at_checked(cut)
            .ok_or_else(|| invalid("invalid probe split"))?;
        let events = projected(vec![
            Bytes::copy_from_slice(head),
            Bytes::copy_from_slice(tail),
        ])
        .await?;
        assert!(
            events
                .iter()
                .any(|event| matches!(event, ModelEvent::ToolCall(call) if call.name == "read"))
        );
        assert!(events.iter().any(
            |event| matches!(event, ModelEvent::MessageCompleted { text } if text == "answer λ")
        ));
        assert!(events.iter().any(|event| matches!(event, ModelEvent::Completed { metadata } if metadata["usage"]["input_tokens"] == 7)));
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, ModelEvent::Content { .. }))
        );
    }
    Ok(())
}

#[tokio::test]
async fn strict_projection_refuses_namespace_and_custom_calls_while_live_decoding_is_unchanged()
-> Result<()> {
    let mut namespaced = ordinary();
    for tool in &mut namespaced.tools {
        tool.namespace = Some("collaboration".into());
    }
    let custom = Step {
        tools: Vec::new(),
        custom_tools: vec![CustomTool {
            id: "call".into(),
            name: "apply_patch".into(),
            namespace: None,
            input: "opaque".into(),
        }],
        ..ordinary()
    };
    for step in [namespaced, custom] {
        assert!(
            projected(chunks(&step)?).await.is_err(),
            "lossy semantics accepted"
        );
        let body = Box::pin(futures::stream::iter(chunks(&step)?.into_iter().map(Ok)));
        let live: Vec<_> =
            super::events_named(Adapter::Responses, body, 65536, dispatch(), None, None)
                .try_collect()
                .await?;
        assert!(
            live.iter()
                .any(|event| matches!(event, ModelEvent::Completed { .. }))
        );
    }
    Ok(())
}

// Mutate the shared encoder's JSON data without introducing another SSE parser
// or encoder: byte substitutions preserve its framing and original specimen.
#[tokio::test]
async fn strict_projection_refuses_unrepresented_terminal_semantics_and_trailing_bytes()
-> Result<()> {
    let original = chunks(&ordinary())?;
    let cases = [
        (
            "\"type\":\"function_call\"",
            "\"type\":\"unknown_output_item\"",
        ),
        ("\"type\":\"output_text\"", "\"type\":\"reasoning_text\""),
        ("\"role\":\"assistant\"", "\"role\":\"user\""),
        ("\"status\":\"completed\"", "\"status\":\"incomplete\""),
        (
            "\"type\":\"output_text\"",
            "\"annotations\":[{\"type\":\"url_citation\"}],\"type\":\"output_text\"",
        ),
        (
            "\"type\":\"function_call\"",
            "\"new_semantics\":true,\"type\":\"function_call\"",
        ),
        (
            "\"type\":\"response.created\"",
            "\"future_semantics\":true,\"type\":\"response.created\"",
        ),
        (
            "\"type\":\"response.output_text.delta\"",
            "\"logprobs\":[{\"token\":\"answer\"}],\"type\":\"response.output_text.delta\"",
        ),
    ];
    for (before, after) in cases {
        let mut changed = false;
        let mutated = original
            .iter()
            .map(|chunk| {
                let text =
                    std::str::from_utf8(chunk).map_err(|_| invalid("invalid probe UTF-8"))?;
                changed |= text.contains(before);
                Ok(Bytes::from(text.replace(before, after)))
            })
            .collect::<Result<Vec<_>>>()?;
        assert!(changed);
        assert!(projected(mutated).await.is_err(), "accepted {after}");
    }
    let mut trailing = original.clone();
    trailing.extend(chunks(&ordinary())?);
    assert!(projected(trailing).await.is_err());
    let mut truncated = original;
    truncated.pop();
    assert!(projected(truncated).await.is_err());
    Ok(())
}

#[tokio::test]
async fn strict_projection_checks_authoritative_items_before_normalization() -> Result<()> {
    for (before, after) in [
        (
            "\"type\":\"function_call\"",
            "\"namespace\":\"hidden\",\"type\":\"function_call\"",
        ),
        (
            "\"type\":\"function_call\"",
            "\"type\":\"custom_tool_call\"",
        ),
        ("\"type\":\"function_call\"", "\"type\":\"future_item\""),
        ("\"name\":\"read\"", "\"name\":\"other\""),
    ] {
        let mut mutated = chunks(&ordinary())?;
        let terminal = mutated
            .last_mut()
            .ok_or_else(|| invalid("missing probe terminal"))?;
        let text = std::str::from_utf8(terminal).map_err(|_| invalid("invalid probe UTF-8"))?;
        assert!(text.contains(before));
        *terminal = Bytes::from(text.replace(before, after));
        assert!(
            projected(mutated).await.is_err(),
            "terminal coverage lost {after}"
        );
    }
    Ok(())
}
